// Rendering helpers for the integrated delivery / cash-settlement model.
import {unionExampleCheck} from './reference-check.js';
export function referenceComparison({escape:esc,amount,warning}){const c=unionExampleCheck();return '<section class="panel"><details><summary>370조원 · 8천초반 연봉 노조 전달 예시 비교</summary><p class="disclosure">'+esc(c.basis)+'. 원문·정확 연봉·업무성과급·세전/세후 정의 미확인으로 공식 검증값이 아닙니다.</p><div class="table-wrap"><table><thead><tr><th>소속</th><th>산식 추정 세전</th><th>전달 대략 예시</th><th>차이</th><th>필요 기초금액 역산</th><th>필요 업무성과급 역산</th></tr></thead><tbody>'+c.rows.map(r=>'<tr><td>'+esc(r.division)+'</td><td>'+amount(r.estimatedGross)+'</td><td>'+amount(r.relayedApproximateTarget)+'</td><td>'+amount(r.difference)+'</td><td>'+amount(r.requiredBasisIfTargetIsPretax)+'</td><td>'+amount(r.requiredWorkBonusIfTargetIsPretax)+'</td></tr>').join('')+'</tbody></table></div><p class="disclosure">메모리7.5억 기준 공통70%=5.25억은 전달5.3억의 반올림 가능성이 있습니다. 파운드리30%=2.25억이며 전달2.4억/7.5억=32%로 현재30%와 다릅니다. 계수나 기준값을 금액에 맞추지 않았습니다.</p>'+warning()+'</details></section>';}
export function integratedNotice(r,s,{escape:esc,amount}){
 const warnings=[...r.pendingOrigins.map(x=>x.origin+'년 OPI2 미확정 · 제외한 부분합계'),...r.calculationWarnings.map(x=>x.origin+'년 '+x.message+' (추가납부 '+amount(x.fundingShortfall)+')')];
 return '<div class="notice">선택한 가정으로 계산한 추정치 · 회사 확정 결과 아님. 지급일 종가 유지 매각, 세금/보험 기본 다음해 현금 정산. '+(s.opi2Policy.repeatFutureYears?'2027 이후도 같은 규칙 적용 가정. ':'미래 동일조건 미선택. ')+(warnings.length?'<strong>'+esc(warnings.join(' / '))+'</strong>':'')+'</div>';
}
export function integratedDetails(r,{escape:esc,amount,stat,warning}){
 const es=r.events.filter(e=>e.type==='opi2');
 const headers=['발생/지급','예상 지급률','세전 G','신고소득 Y','선제 세금 H','선제 보험 I','기부 D','주식 원가기준 예산','지급 종가 주식가치','주식 시장평가 조정','최종 세금 추정','최종 보험 추정','정산 일정/현금'];
 const cells=es.map(e=>[e.origin+' / '+e.payYear+(e.assumedDelivery?' (지급예정 가정)':''),((e.policyRow.rate??0)*100).toFixed(4)+'%'+(e.policyRow.rateSource==='legacy'?' · 전망률':' · 직접률'),amount(e.gross),amount(e.taxableIncome),amount(e.snapshot.withheldTax),amount(e.snapshot.withheldInsurance),amount(e.snapshot.donation),amount(e.snapshot.benchmarkStockBudget),e.snapshot.estimatedStockMarketValue===null?'미완료 · 추가납부 '+amount(e.snapshot.fundingShortfall):amount(e.snapshot.estimatedStockMarketValue),e.marketAdjustment===null?'미완료':amount(e.marketAdjustment),amount(e.finalTaxEstimate),amount(e.finalInsuranceEstimate),e.settlements.map(t=>t.year+'년 '+(t.kind==='tax'?'세금':'보험')+' '+amount(t.net)).join(' / ')]);
 return '<section class="panel"><h2>지급 주식 · 최종 부담 · 현금 정산 원장</h2><p class="disclosure">세후 발생가치 = 주식예산의 종가평가 + 선제 세금/보험 − 최종 증분 부담. 환급/추징은 주식수와 분리한 현금입니다. 실제 입고 확정주수·최종 납부액은 확인 대기이며 아래는 추정치입니다.</p><div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+cells.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="grid three" style="margin-top:14px">'+stat('기간 이후 정산채권 · 환급 예정',amount(r.locked.settlementReceivable),'cash')+stat('기간 이후 정산채무 · 추가납부 예정',amount(r.locked.settlementPayable),'difference')+stat('기간 내 정산 현금 순유입',amount(r.totals.settlementInPeriod),'cash')+'</div><p class="disclosure">원가 장부: G = 주식예산 + H + I + D. 종가평가 조정 = 순환산주수 × (종가 − 기준가). 전체 원장: 기초잔액 + 세후 발생 = 기간 현금화 + 기말 주식 + 기말 현금성 보상/정산채권·채무. 잔여 원 최대잔여법 분배 · 차이 '+r.accounting.difference.toLocaleString()+'원'+(r.accounting.complete?'':' (추가납부 회차 때문에 미완료)')+'.</p>'+warning()+'<details><summary>발생·지급·정산·원단위 보존 JSON 로그</summary><pre class="log">'+esc(JSON.stringify({accounting:r.accounting,events:es,taxLog:r.taxLog,pending:r.pendingOrigins,warnings:r.calculationWarnings},null,2))+'</pre></details></section>';
}
